"""Consolidate recorded evidence; publishing is an explicit separate action.

--final requires the scheduled deadline or an actually resolved exact bracket.
It never upgrades a numerical candidate or solver status to a theorem.
"""
import argparse,json,datetime,time,subprocess,hashlib,math
from pathlib import Path
from checkpoint_io import write_text
from progress_dashboard import CAMPAIGNS,update,read
ROOT=Path(__file__).resolve().parents[1]
REPO='https://github.com/returnedlegend/gcm-logconcave-counterexamples'
def link(path,label=None):return f'[{label or path}]({REPO}/blob/main/{path})'
def render(final=False):
 now=datetime.datetime.now(datetime.timezone.utc);schedule=read(ROOT/'checkpoints/overnight_schedule.json');research=read(ROOT/'checkpoints/research_status.json');deadline=datetime.datetime.fromisoformat(schedule['deadline_utc'])
 if final and now<deadline and not research.get('exact_minimal_order_resolved'):raise RuntimeError('Scheduled research time remains; do not publish a final briefing yet')
 states={name:read(ROOT/f'checkpoints/{name}.json') for name in CAMPAIGNS};totals=update();bounds=(research['lower_bound'],research['upper_bound']);cert=read(ROOT/research['negative_witness_certificate']);resources=read(ROOT/'checkpoints/resource_observations.json')
 lines=['# Overnight research results: log-concave GCM','',('Final scheduled-run report' if final else '**Provisional report — research is still running.**'),f"Updated {now:%Y-%m-%d %H:%M:%S UTC}. Scheduled interval: {schedule['start_utc']} to {schedule['deadline_utc']}.",'']
 if research.get('exact_minimal_order_resolved'):lines+=[f'**The verified minimal order is m* = {bounds[0]}.**']
 else:lines+=[f'**The exact minimal order remains unresolved. The verified bracket is {bounds[0]} ≤ m* ≤ {bounds[1]}.**']
 lines += ['',f"Exact rational certificates, with downward propagation along heat flow, establish nonnegative signs at orders {', '.join(map(str,research['nonnegative_orders']))}. The positive-time smoothing and endpoint hypotheses are stated explicitly in the note. A strictly log-concave order-{bounds[1]} density has a rigorously negative entropy derivative.",'','The convention is Boltzmann entropy `H = integral p log p`, with heat generator `(1/2) d²/dx²`. The opposite entropy convention reverses the signs.','','## Concrete counterexample','']
 if bounds[1]==16 and cert.get('parameters',{}).get('amplitudes')==['1/15','1/40000','-1/18000000'] and cert['parameters']['kappa']=='1/14':
  lines += ['```text','p(x) = exp(-x²/28)','       * (1 + cos(x)/15 + cos(2*x)/40000 - cos(3*x)/18000000) / Z','Z = sqrt(28*pi)','    * (1 + exp(-7)/15 + exp(-28)/40000','         - exp(-63)/18000000)','```','','Exact global minimum curvature: `min V\'\' = 25777/235206314 > 1/10000`.','Certified signed derivative: `S16 < -3/4`, with an enclosure near `-0.76971250884778794609`.']
 else:lines+=['Exact parameters:','```json',json.dumps(cert['parameters'],indent=2),'```',f"Signed derivative enclosure: `{cert['signed_derivative_interval']}`.",f"Global curvature bound: `{cert.get('convexity_lower_bound','see certificate')}`."]
 lines += ['',link(research['negative_witness_certificate'],'Primary interval certificate')+'.']
 if research.get('curvature_certificate'):lines += [link(research['curvature_certificate'],'Exact global minimum-curvature proof')+'.']
 independent=research.get('independent_negative_witness_certificate')
 if independent:lines += [link(independent,'Independent interval calculation')+'. The spatial score-polynomial and exact heat-density calculations agree. Both include rigorous infinite-tail bounds.']
 lines += ['','## Orders 6, 7, and 8','','| Order | Sharp proven lower bound for S_m Var(p)^m | Best recorded numerical value |','|---|---:|---:|']
 for m,bound in [(6,60),(7,360),(8,2520)]:
  values=[s.get('best',{}).get(str(m),{}).get('normalized',float('inf')) for s in states.values() if isinstance(s.get('best'),dict)];v=min(values,default=float('inf'));lines.append(f'| {m} | {bound} | {v:.14g} |' if math.isfinite(v) else f'| {m} | {bound} | unavailable |')
 lines += ['','The sharp bound `S_m Var(p)^m ≥ (m-1)!/2` is independently verified throughout orders 6–11; the additional constants at orders 9, 10, and 11 are 20,160, 181,440, and 1,814,400.','', 'An additional exact certificate excludes the entire family `p ∝ exp(beta*x) cosh(x)^(-alpha)`, `alpha > |beta|`, at orders 2–17. Its beta-moment and Bernstein identities were independently checked; this is a family-specific result, not a larger universal lower bound.','', 'The Gaussian uniquely attains these proven bounds. For a normalized minimizing sequence, the relative score discrepancy from the matching Gaussian tends to zero; the note gives an explicit bound. Numerical values can differ in their last digits because of rounding; they are not the proof. The infimum of the unnormalized derivative is zero under dilation, so normalization is essential.','',link('certs/exact_mckean_m6.json')+', '+link('certs/exact_mckean_m7.json')+', '+link('certs/exact_mckean_m8.json')+'.','','## Hardware and actual work','','GPU: NVIDIA RTX A6000, 49,140 MiB reported memory. The environment exposed 8 CPU cores and 62.8 GiB host RAM; these observed values differ from the requested 6-core/48-GB specification. The filesystem reported about 206.9 GB total capacity. PyTorch/CUDA executed the search; it was not a CPU-only run.','','Production FP32 candidate evaluations: **'+f"{totals['gpu_evaluations']:,}"+'**.','Recorded FP64 refined candidates: **'+f"{totals['refinement_evaluations']:,}"+'**. These are evaluations, not necessarily unique densities; warmups/readiness tests and uncheckpointed interrupted partial generations are excluded.','','| Campaign | Saved status | FP32 evaluations | FP64 refinements |','|---|---|---:|---:|']
 for name,s in states.items():
  if s:lines.append(f"| {name} | {s.get('status','unknown')} | {s.get('gpu_evaluations',0):,} | {s.get('refinement_evaluations',0):,} |")
 lines += ['','Campaign B used 65,536 simultaneous FP32 candidates, selected 512 elites, and used FP64 refinement with 2,049- and 4,097-point resolution checks. Campaign C uses a periodic GPU approximation only to screen rationalized parameters; retained negative results require full spatial Arb certification. Supplementary searches include polynomial curvature, signed higher harmonics, asymmetric phases, localized Fourier modes, convex quartic deformations, two interacting base frequencies, and positive-curvature lattices.','']
 if resources:lines += [f"Resource sampling began at {resources.get('sampling_started_utc')}; {resources.get('samples',0)} observations were recorded. Maximum observed host nonavailable-memory estimate: {resources.get('max_host_used_bytes_upper_bound',0)/1024**3:.2f} GiB. Maximum sampled GPU memory use during that monitoring interval: {resources.get('max_gpu_used_mib',0):,} MiB. Earlier compiled-batch validation measured a 5.73-GB allocation. Sampling is not a continuous proof of a resource bound. Certification process pools were capped at four workers.",'']
 lines += ['## Validation, limitations, and files','','Formula tests at orders 6–8 passed the requested 1e-11 relative-error threshold against high-precision positive-time heat-convolution finite differences. Exact rational SOS identities were checked by a separate standard-library verifier. The counterexample has two different interval proof routes. Recovery checks exercised OOM handling and the bounded certification pool.','','Several CPU jobs exited with code 143 without a Python traceback. Their saved results were preserved, incomplete runs were not represented as completed, and proof jobs were restarted with heartbeat/exit supervision. Numerical SDP failures and indefinite Gram matrices are explicitly not proofs of either positivity or failure. See '+link('certs/process_interruptions.json')+'.','','A finite search cannot prove a universal lower bound. The lower end of the bracket comes from exact certificates, not search minima. The remaining orders inside the bracket have not been resolved globally. No claim of novelty or peer review is made.','', '- '+link('paper/draft_note.pdf','Research note PDF'),'- '+link('paper/draft_note.tex','LaTeX source'),'- '+link('README.md','CPU-only reproduction instructions'),'- '+link('checkpoints/research_status.json','Verified bracket and certificate hashes'),'- '+link('certs/formula_tests.json','Formula validation'),'- '+link('certs/witness_order_table.json','Certified derivative table for the explicit witness'),'- '+link('notes_literature.md','Literature verification'),'- '+link('PROGRESS.md','Progress and recorded counts'),'','Local working logs are in `logs/`; raw logs are excluded from Git. Source code, JSON checkpoints, proof certificates, the note, and this briefing are tracked.','', 'Primary background: [Zou et al.](https://arxiv.org/abs/2608.30275), [Gu and Sellke](https://arxiv.org/abs/2605.11656), and [Wang](https://arxiv.org/abs/2408.13957).']
 write_text(ROOT/'MORNING_BRIEFING.md','\n'.join(lines)+'\n');return ROOT/'MORNING_BRIEFING.md'

def post():
 receipt=ROOT/'certs/github_issue.json'
 if receipt.exists():raise RuntimeError('A GitHub issue receipt already exists; do not duplicate the issue')
 path=render(final=True);p=subprocess.run(['gh','issue','create','--title','Overnight Research Results: GCM Minimal Order m*','--body-file',str(path)],cwd=ROOT,text=True,capture_output=True,timeout=60)
 if p.returncode:raise RuntimeError(p.stderr)
 receipt.write_text(json.dumps({'url':p.stdout.strip(),'posted_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'briefing_sha256':hashlib.sha256(path.read_bytes()).hexdigest()},indent=2)+'\n');return p.stdout.strip()
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--final',action='store_true');p.add_argument('--post',action='store_true');a=p.parse_args();print(post() if a.post else render(a.final))
